import fs from 'node:fs';
import { JSDOM } from 'jsdom';

const dom = new JSDOM('<!DOCTYPE html><body></body>', { pretendToBeVisual: true });
globalThis.window = dom.window;
globalThis.document = dom.window.document;
globalThis.navigator = dom.window.navigator;
globalThis.DOMPurify = undefined;

const { default: mermaid } = await import('mermaid');
mermaid.initialize({ startOnLoad: false, securityLevel: 'loose' });

const mmd = fs.readFileSync('C:\\Users\\olive_\\OneDrive\\Documentos\\codigo\\Momma\\momma-stock-insight\\tmp\\diagram.mmd', 'utf8');
try {
  const res = await mermaid.parse(mmd);
  console.log('PARSE OK', JSON.stringify(res));
  process.exit(0);
} catch (e) {
  console.error('PARSE FAIL', e && e.message ? e.message : String(e));
  process.exit(1);
}

